/**
 * Seeds a Supabase/Postgres database with the same company the demo shows.
 *
 *   1. Put DATABASE_URL and DIRECT_URL in .env
 *   2. npm run db:push      (creates the tables)
 *   3. npm run db:seed      (this file)
 *
 * It reuses src/lib/seed.ts, so the demo data and the database data are
 * generated by exactly one piece of code.
 */
import { PrismaClient } from "@prisma/client";
import { buildCompany, CO } from "../src/lib/seed";

const prisma = new PrismaClient();

const TYPE_MAP: Record<string, string> = {
  "Full Time": "FULL_TIME", "Part Time": "PART_TIME", "Contract": "CONTRACT",
  "Internship": "INTERNSHIP", "Freelance": "FREELANCE",
};
const WORK_MAP: Record<string, string> = { "Remote": "REMOTE", "Hybrid": "HYBRID", "On-site": "ON_SITE" };
const STATUS_MAP: Record<string, string> = {
  "Active": "ACTIVE", "On Leave": "ON_LEAVE", "Suspended": "SUSPENDED",
  "Terminated": "TERMINATED", "Resigned": "RESIGNED", "Probation": "PROBATION",
};

async function main() {
  const c = buildCompany();

  const company = await prisma.company.create({
    data: {
      name: CO.name, email: CO.email, phone: CO.phone, website: CO.site,
      address: CO.address, taxNumber: CO.ntn, currency: "PKR", timezone: "Asia/Karachi",
    },
  });
  console.log("Company created:", company.name);

  const deptIds = new Map<string, string>();
  for (const d of c.departments) {
    const row = await prisma.department.create({
      data: { companyId: company.id, name: d.name, code: d.code, budget: d.budget },
    });
    deptIds.set(d.id, row.id);
  }
  console.log(`${c.departments.length} departments`);

  const empIds = new Map<string, string>();
  for (const e of c.employees) {
    const row = await prisma.employee.create({
      data: {
        companyId: company.id, employeeCode: e.code, firstName: e.first, lastName: e.last,
        workEmail: e.email, phone: e.phone, dateOfBirth: e.dob, gender: e.gender, address: e.address,
        emergencyName: e.emergency.name, emergencyPhone: e.emergency.phone, emergencyRel: e.emergency.rel,
        joiningDate: e.joined,
        employmentType: TYPE_MAP[e.type] as never,
        workType: WORK_MAP[e.work] as never,
        status: STATUS_MAP[e.status] as never,
        statusReason: e.statusMeta?.reason ?? null,
        workLocation: e.location,
        departmentId: deptIds.get(e.deptId),
        salary: {
          create: {
            basic: e.salary.basic, housingAllowance: e.salary.housing,
            transportAllowance: e.salary.transport, medicalAllowance: e.salary.medical,
            taxRate: e.salary.taxRate, loanInstallment: e.salary.loan,
            effectiveFrom: new Date(2026, 7, 1),
          },
        },
      },
    });
    empIds.set(e.id, row.id);
  }
  console.log(`${c.employees.length} employees with salary structures`);

  // Managers and department heads need the employees to exist first.
  for (const e of c.employees) {
    if (e.mgrId) {
      await prisma.employee.update({
        where: { id: empIds.get(e.id)! },
        data: { managerId: empIds.get(e.mgrId) },
      });
    }
  }
  for (const d of c.departments) {
    await prisma.department.update({
      where: { id: deptIds.get(d.id)! },
      data: { headId: empIds.get(d.head) },
    });
  }

  for (const t of c.leaveTypes) {
    await prisma.leaveType.create({
      data: { companyId: company.id, name: t.name, daysPerYear: t.days, isPaid: t.paid, carryForward: t.carry },
    });
  }

  const projIds = new Map<string, string>();
  for (const p of c.projects) {
    const row = await prisma.project.create({
      data: {
        companyId: company.id, name: p.name, code: p.code, description: p.desc,
        clientName: p.client, startDate: p.start, deadline: p.due,
        status: p.status.toUpperCase().replace(" ", "_") as never,
        priority: p.priority.toUpperCase() as never,
        budget: p.budget, spent: p.spent, progress: p.progress,
        managerId: empIds.get(p.pm),
        members: { create: p.team.map(id => ({ employeeId: empIds.get(id)! })) },
      },
    });
    projIds.set(p.id, row.id);
  }
  console.log(`${c.projects.length} projects`);

  for (const t of c.tasks) {
    await prisma.task.create({
      data: {
        companyId: company.id, projectId: projIds.get(t.pid)!, title: t.title,
        assigneeId: empIds.get(t.assignee), priority: t.priority.toUpperCase() as never,
        status: t.status.toUpperCase().replace(/ /g, "_") as never,
        startDate: t.start, dueDate: t.due,
      },
    });
  }
  console.log(`${c.tasks.length} tasks`);
  console.log("\nSeed complete. Sign in as zeeshan.haider@divineesoft.com once auth is wired.");
}

main()
  .catch(e => { console.error(e); process.exit(1); })
  .finally(() => prisma.$disconnect());
